import{_ as e,H as i,f as t,i as l}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"练习：问题的归约与不可解性","description":"","frontmatter":{},"headers":[{"level":2,"title":"看完了","slug":"看完了","link":"#看完了","children":[]}],"relativePath":"算法（第4版）/练习：问题的归约与不可解性.md","filePath":"算法（第4版）/练习：问题的归约与不可解性.md","lastUpdated":1795559298000}'),p={name:"算法（第4版）/练习：问题的归约与不可解性.md"};function A(a,E,n,s,B,o){return i(),t("div",null,[...E[0]||(E[0]=[l('<h1 id="练习-问题的归约与不可解性" tabindex="-1">练习：问题的归约与不可解性 <a class="header-anchor" href="#练习-问题的归约与不可解性" aria-label="Permalink to &quot;练习：问题的归约与不可解性&quot;">​</a></h1><p>6.49 找到 37 703 491 的一个非平凡因数。</p><p>6.50 证明最短路径问题可以归约为线性规划问题。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%AE%97%E6%B3%95%EF%BC%88%E7%AC%AC4%E7%89%88%EF%BC%89/images/%25E7%25BB%2583%25E4%25B9%25A0%25EF%25BC%259A%25E9%2597%25AE%25E9%25A2%2598%25E7%259A%2584%25E5%25BD%2592%25E7%25BA%25A6%25E4%25B8%258E%25E4%25B8%258D%25E5%258F%25AF%25E8%25A7%25A3%25E6%2580%25A7/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%AE%97%E6%B3%95%EF%BC%88%E7%AC%AC4%E7%89%88%EF%BC%89/images/%25E7%25BB%2583%25E4%25B9%25A0%25EF%25BC%259A%25E9%2597%25AE%25E9%25A2%2598%25E7%259A%2584%25E5%25BD%2592%25E7%25BA%25A6%25E4%25B8%258E%25E4%25B8%258D%25E5%258F%25AF%25E8%25A7%25A3%25E6%2580%25A7/1.png" alt=""></a></p><p>6.51 如果 P ≠ NP，是否存在能够在</p><ul><li>时间内解决某个 NP- 完全问题的算法？解释你的</li></ul><p>回答。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%AE%97%E6%B3%95%EF%BC%88%E7%AC%AC4%E7%89%88%EF%BC%89/images/%25E7%25BB%2583%25E4%25B9%25A0%25EF%25BC%259A%25E9%2597%25AE%25E9%25A2%2598%25E7%259A%2584%25E5%25BD%2592%25E7%25BA%25A6%25E4%25B8%258E%25E4%25B8%258D%25E5%258F%25AF%25E8%25A7%25A3%25E6%2580%25A7/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%AE%97%E6%B3%95%EF%BC%88%E7%AC%AC4%E7%89%88%EF%BC%89/images/%25E7%25BB%2583%25E4%25B9%25A0%25EF%25BC%259A%25E9%2597%25AE%25E9%25A2%2598%25E7%259A%2584%25E5%25BD%2592%25E7%25BA%25A6%25E4%25B8%258E%25E4%25B8%258D%25E5%258F%25AF%25E8%25A7%25A3%25E6%2580%25A7/2.png" alt=""></a></p><p>6.52 假设某人发明了一种保证能够在与</p><ul><li><p>成正比的时间内解决布尔可满足性问题的算法。</p></li><li><p>成正比的时间内解决其他 NP- 完全问题吗？</p></li></ul><p>这说明我们能够在与</p><p>6.53 一个能够在与</p><ul><li>成正比的时间内解决整数线性规划问题的程序的意义是什么？</li></ul><p>6.54 给出一个从顶点覆盖问题向 0-1 整数线性不等式可满足性问题的多项式时间的归约。</p><p>6.55 使用无向图中的汉密尔顿路径问题的 NP- 完全性证明在有向图中寻找汉密尔顿路径的问题也是 NP- 完全的。</p><p>6.56 假设两个问题都已知是 NP- 完全的，这说明能够在多项式时间内将两者相互归约吗？</p><p>6.57 假设问题</p><ul><li>是 NP- 完全的，能够在多项式时间内归约为问题也能在多项，而且</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%AE%97%E6%B3%95%EF%BC%88%E7%AC%AC4%E7%89%88%EF%BC%89/images/%25E7%25BB%2583%25E4%25B9%25A0%25EF%25BC%259A%25E9%2597%25AE%25E9%25A2%2598%25E7%259A%2584%25E5%25BD%2592%25E7%25BA%25A6%25E4%25B8%258E%25E4%25B8%258D%25E5%258F%25AF%25E8%25A7%25A3%25E6%2580%25A7/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%AE%97%E6%B3%95%EF%BC%88%E7%AC%AC4%E7%89%88%EF%BC%89/images/%25E7%25BB%2583%25E4%25B9%25A0%25EF%25BC%259A%25E9%2597%25AE%25E9%25A2%2598%25E7%259A%2584%25E5%25BD%2592%25E7%25BA%25A6%25E4%25B8%258E%25E4%25B8%258D%25E5%258F%25AF%25E8%25A7%25A3%25E6%2580%25A7/3.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%AE%97%E6%B3%95%EF%BC%88%E7%AC%AC4%E7%89%88%EF%BC%89/images/%25E7%25BB%2583%25E4%25B9%25A0%25EF%25BC%259A%25E9%2597%25AE%25E9%25A2%2598%25E7%259A%2584%25E5%25BD%2592%25E7%25BA%25A6%25E4%25B8%258E%25E4%25B8%258D%25E5%258F%25AF%25E8%25A7%25A3%25E6%2580%25A7/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%AE%97%E6%B3%95%EF%BC%88%E7%AC%AC4%E7%89%88%EF%BC%89/images/%25E7%25BB%2583%25E4%25B9%25A0%25EF%25BC%259A%25E9%2597%25AE%25E9%25A2%2598%25E7%259A%2584%25E5%25BD%2592%25E7%25BA%25A6%25E4%25B8%258E%25E4%25B8%258D%25E5%258F%25AF%25E8%25A7%25A3%25E6%2580%25A7/4.png" alt=""></a></p><ul><li>一定是 NP- 完全的吗？</li></ul><p>式时间内归约为</p><ul><li><p>，那么</p></li><li><p>不一定属于 NP。</p></li></ul><p>答：不，因为</p><p>6.58 假设我们有一个能够解决布尔可满足性问题的确定性版本的算法，这说明存在某种变量赋值能够满足所有的布尔表达式。说明如何找到这种赋值方案。</p><p>6.59 假设我们有一个能够解决顶点覆盖问题的确定性版本的算法，这说明对于某个给定的大小存在顶点覆盖的方案。说明如何解决最小顶点覆盖问题的最优化版本。</p><p>6.60 解释为何顶点覆盖问题的最优化版本不一定是一个搜索问题。</p><p>答：因为并没有很好的方法来验证给定的节是否是最优的。（尽管我们可以用二分查找在这个问题的搜索版本上找到最优解。）</p><p>6.61 假设问题</p><ul><li>和问题均为搜索问题，且能够在多项式时间内归约为。我们可以得</li></ul><p>到以下哪些结论。</p><p>a. 如果</p><ul><li>是 NP- 完全的，那么也是。</li></ul><p>b. 如果</p><ul><li>是 NP- 完全的，那么也是。</li></ul><p>c. 如果</p><ul><li>属于 P，那么也属于 P。</li></ul><p>d. 如果</p><ul><li>属于 P，那么也属于 P。</li></ul><p>6.62 假设 P ≠ NP，我们可以得到以下哪些结论。</p><p>a. 如果问题</p><ul><li>是 NP- 完全的，那么无法在多项式时间内得到解决。</li></ul><p>b. 如果问题</p><ul><li>属于 NP，那么无法在多项式时间内得到解决。</li></ul><p>c. 如果问题</p><ul><li>属于 NP 但并不是 NP- 完全的，那么可以在多项式时间内得到解决。</li></ul><p>d. 如果问题</p><ul><li>属于 P，那么就不是 NP- 完全的。</li></ul><h2 id="看完了" tabindex="-1">看完了 <a class="header-anchor" href="#看完了" aria-label="Permalink to &quot;看完了&quot;">​</a></h2><p>如果您对本书内容有疑问，可发邮件至 <a href="mailto:contact@turingbook.com" target="_blank" rel="noreferrer">contact@turingbook.com</a>，会有编辑或作译者协助答疑。也可访问图灵社区，参与本书讨论。</p><p>如果是有关电子书的建议或问题，请联系专用客服邮箱：ebook@turingbook.com。</p><p>在这里可以找到我们：</p><ul><li><p>微博 @图灵教育 : 好书、活动每日播报</p></li><li><p>微博 @图灵社区 : 电子书和好文章的消息</p></li><li><p>微博 @图灵新知 : 图灵教育的科普小组</p></li><li><p>微信 图灵访谈 : ituring_interview，讲述码农精彩人生</p></li><li><p>微信 图灵教育 : turingbooks</p></li></ul>',53)])])}const g=e(p,[["render",A]]);export{u as __pageData,g as default};
